route(req) {
  const deadline = monotonicNow() + req.remainingMs;
  for (let attempt = 1; attempt <= policy.maxAttempts; attempt++) {
    if (monotonicNow() >= deadline) throw DeadlineExceeded;
    const endpoint = eligibleSnapshot().nextRoundRobin();
    if (!endpoint) throw Unavailable;
    const permit = tryAcquire(endpoint); if (!permit) throw Overloaded;
    let result;
    try { result = await call(endpoint, req, deadline); }
    finally { release(permit); }
    if (result.ok) return result;
    if (!retrySafe(req) || !result.retryable || !retryBudget.take()) return result;
    await boundedJitterBackoff(deadline);
  }
  throw AttemptsExhausted;
}

